// V2.9.8.1 admission safety rules: rank-based 冲稳保, shared by A/B/C and detail cards.
(function(){
  function num(v){ if(v===null||v===undefined||v==='') return null; const n=Number(String(v).replace(/[^\d.-]/g,'')); return Number.isFinite(n)?n:null; }
  function fmt(v){ const n=num(v); return n===null?'-':Math.round(n).toLocaleString('zh-CN'); }
  function currentRank(){
    const dom=num(document.getElementById('myRank')?.value);
    if(dom!==null) return dom;
    try{ const r=(typeof resolveRank==='function')?resolveRank():null; if(num(r)!==null) return num(r); }catch(e){}
    try{ if(num(window.currentRank)!==null) return num(window.currentRank); }catch(e){}
    return null;
  }
  function model(){ return document.getElementById('model')?.value || 'normal'; }
  function thresholds(){
    const m=model();
    if(m==='safe') return {bao:6500,wen:2200,xiao:-800,chong:-3200};
    if(m==='bold') return {bao:3500,wen:800,xiao:-2300,chong:-6500};
    return {bao:5000,wen:1500,xiao:-1500,chong:-5000};
  }
  function legacyLabel(level){
    if(level==='保底') return '保';
    if(level==='稳妥') return '稳';
    if(level==='匹配') return '稳';
    if(level==='可冲') return '小冲';
    if(level==='超冲') return '冲';
    if(level==='过低') return '保';
    return '观察';
  }
  function classify(record){
    const line=num(record?.rank2025);
    const cr=currentRank();
    const th=thresholds();
    if(line===null || cr===null){
      const label=legacyLabel(record?._level);
      return {label, level:label==='保'?1:label==='稳'?2:label==='小冲'?3:label==='冲'?4:5, deltaRank:null, tone:'unknown', text:record?._level?`按当前层级先标为“${label}”，输入位次后可细化。`:'输入位次后判断录取安全。'};
    }
    const delta=line-cr; // positive means the candidate's 2025 line is behind the student's rank -> safety margin.
    let label='需谨慎', level=5, tone='caution', text='缺口较大或数据波动明显，需要接受较强不确定性。';
    if(delta>=th.bao){ label='保'; level=1; tone='safe'; text=`相对有安全垫，2025线比孩子位次靠后约 ${fmt(delta)} 位。`; }
    else if(delta>=th.wen){ label='稳'; level=2; tone='steady'; text=`位次接近合理区间，约有 ${fmt(delta)} 位余量。`; }
    else if(delta>=th.xiao){ label='小冲'; level=3; tone='near'; text=delta>=0?`贴近2025线，约有 ${fmt(delta)} 位余量。`:`略高于当前位次，约需向上 ${fmt(Math.abs(delta))} 位。`; }
    else if(delta>=th.chong){ label='冲'; level=4; tone='stretch'; text=`2025线高出当前位次约 ${fmt(Math.abs(delta))} 位，需要接受不确定性。`; }
    return {label, level, deltaRank:delta, currentRank:cr, lineRank:line, tone, text, disclaimer:'录取安全仅作初筛参考，最终以当年招生计划和实际投档为准。'};
  }
  window.LN_ADMISSION_SAFETY_RULES_V2981={classify,currentRank,fmt,ready:true};
})();
// ===== END assets/admission-safety-rules.v2981.js =====

// ===== BEGIN assets/admission-evidence-rules.v2981.js =====
// V2.9.8.1 admission evidence rules: 2025/2024 score-rank evidence and comparability.
(function(){
  function num(v){ if(v===null||v===undefined||v==='') return null; const n=Number(String(v).replace(/[^\d.-]/g,'')); return Number.isFinite(n)?n:null; }
  function fmt(v){ const n=num(v); return n===null?'-':Math.round(n).toLocaleString('zh-CN'); }
  function line(score, rank, year){
    const s=num(score), r=num(rank);
    if(s===null && r===null) return `${year}：暂无可比记录`;
    return `${year}：${s!==null?fmt(s)+'分':'分数待核验'}｜${r!==null?fmt(r)+'位':'位次待核验'}`;
  }
  function rankDiff(record){
    const explicit=num(record?.rankDiff), r25=num(record?.rank2025), r24=num(record?.rank2024);
    if(explicit!==null) return explicit;
    if(r25!==null && r24!==null) return r25-r24;
    return null;
  }
  function possibleNameChanged(record){
    const tags=String(record?.admissionReviewTags||record?.reviewStatus||record?.admissionReviewStatus||'');
    return /待复核|低可信|名称|大类|方向|校企|新增|变更/.test(tags);
  }
  function build(record){
    const y2025=line(record?.score2025, record?.rank2025, '2025');
    const y2024=line(record?.score2024, record?.rank2024, '2024');
    const r25=num(record?.rank2025), r24=num(record?.rank2024);
    const d=rankDiff(record);
    const comparable = r25!==null && r24!==null && !possibleNameChanged(record);
    if(r25===null){ return {y2025,y2024, trend:'2025位次待核验', tone:'unknown', comparable:false, diff:null, tag:'证据待核验', note:'缺少2025位次，先不要按录取安全下结论。'}; }
    if(r24===null){ return {y2025,y2024, trend:'2024暂无可比记录', tone:'unknown', comparable:false, diff:null, tag:'2024缺记录', note:'仅能按2025投档线做初筛，正式填报前建议查招生计划变化。'}; }
    if(!comparable){ return {y2025,y2024, trend:'两年口径需复核', tone:'review', comparable:false, diff:d, tag:'口径需复核', note:'招生名称、专业方向或大类口径可能变化，不强行判断收紧/放宽。'}; }
    const abs=Math.abs(d||0);
    if(abs<300){ return {y2025,y2024, trend:`位次变化 ${fmt(abs)} 位，基本稳定`, tone:'stable', comparable:true, diff:d, tag:'两年稳定', note:''}; }
    if(d<0){ return {y2025,y2024, trend:`较2024收紧 ${fmt(abs)} 位`, tone:'hotter', comparable:true, diff:d, tag:'2025收紧', note:'竞争变强只作观察，不代表下一年必然继续收紧。'}; }
    return {y2025,y2024, trend:`较2024放宽 ${fmt(abs)} 位`, tone:'looser', comparable:true, diff:d, tag:'2025放宽', note:'相对好进需结合计划数、学费和校区变化复核。'};
  }
  window.LN_ADMISSION_EVIDENCE_RULES_V2981={build,line,rankDiff,fmt,ready:true};
})();
// ===== END assets/admission-evidence-rules.v2981.js =====

// ===== BEGIN assets/candidate-decision-tags.v2981.js =====
// V2.9.8.1 decision tag rules: short clickable reminders for candidate cards.
(function(){
  function esc(v){ return String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s])); }
  function interest(record){ return window.LN_CHILD_INTEREST_RUNTIME_V296?.matchRecord?.(record) || null; }
  function hasConfusable(record){ try{return !!(typeof hasConfusableMajorV2946==='function' && hasConfusableMajorV2946(record));}catch(e){return false;} }
  function profile(){ return (window.LN_STUDENT_PROFILE_RULES_V298 || window.LN_STUDENT_PROFILE_RULES_V2976 || window.LN_STUDENT_PROFILE_RULES_V2975)?.deriveProfile?.() || {}; }
  function uniqTags(tags){ const seen=new Set(); return tags.filter(t=>{ const k=t.label+'|'+t.type; if(seen.has(k))return false; seen.add(k); return true; }).sort((a,b)=>(b.priority||0)-(a.priority||0)); }
  function build(record, opts){
    const type=opts?.type||''; const tags=[];
    const safety=window.LN_ADMISSION_SAFETY_RULES_V2981?.classify?.(record);
    if(safety?.label) tags.push({label:safety.label,type:'safety',priority:100,detail:`${safety.text} ${safety.disclaimer||'录取安全仅作初筛参考。'}`,tone:safety.tone});
    const im=interest(record);
    if(im?.active && im.level && im.level!=='no'){
      const label=im.level==='core'?'正主匹配':im.level==='near'?'相近方向':'需复核方向';
      tags.push({label,type:'interest',priority:94,detail:`孩子关注“${esc(im.group?.name||'兴趣方向')}”，系统先转成本科目录规则，再在当前真实候选中匹配；不会生成不存在的专业。`,tone:im.level});
    }else if(im?.active){
      tags.push({label:'综合备选',type:'interest',priority:54,detail:'未直接命中孩子关注点，但仍符合当前位次和家庭底线，保留为综合备选。',tone:'soft'});
    }
    const ev=window.LN_ADMISSION_EVIDENCE_RULES_V2981?.build?.(record);
    if(ev?.tag) tags.push({label:ev.tag,type:'evidence',priority:82,detail:`${ev.y2025}；${ev.y2024}；${ev.trend}${ev.note?'。'+ev.note:''}`,tone:ev.tone});
    const nature=record?.schoolNature?.label || record?.schoolNatureLabel || '';
    if(/公办/.test(nature)) tags.push({label:'公办',type:'family',priority:74,detail:'学校性质识别为公办倾向，正式填报前仍建议以官方招生章程和教育部平台为准。',tone:'ok'});
    if(record?.isHighFee || record?.isCoopV29475) tags.push({label:'高收费复核',type:'family',priority:96,detail:'涉及中外合作或高收费属性，建议单独核验证书、培养地点、学费总成本和转专业政策。',tone:'warn'});
    else if(!(record?.isPrivateV29475)) tags.push({label:'费用可控',type:'family',priority:70,detail:'当前未识别为高收费或中外合作，但学费、住宿、校区仍需以招生计划为准。',tone:'soft'});
    if(record?._qualificationGate?.matched || (record?.qualificationGatesV296||[]).length) tags.push({label:'资格入口',type:'review',priority:98,detail:'该候选可能属于资格型入口，未确认资格前不宜和普通批候选直接混排。',tone:'warn'});
    if(hasConfusable(record)) tags.push({label:'需复核：易混',type:'review',priority:97,detail:'该专业容易与同校或同主题专业混淆，建议对比本科专业代码、专业类和培养方案。',tone:'warn'});
    if(record?.officialMajorCode || record?.undergradMajorCode || record?.catalog_major_code) tags.push({label:'代码可查',type:'review',priority:60,detail:`本科目录代码：${esc(record.officialMajorCode||record.undergradMajorCode||record.catalog_major_code)}。建议与招生章程原文再核对。`,tone:'soft'});
    else tags.push({label:'需复核：代码',type:'review',priority:88,detail:'招生名称和本科目录专业不一定完全一致，建议查看招生章程中的专业代码、培养方案和专业方向。',tone:'warn'});
    const p=profile();
    if((p.reviewTags||[]).includes('misread_review')) tags.push({label:'需分清热门词',type:'profile',priority:78,detail:'孩子当前对专业理解还不充分，建议重点分清专业名、专业类、培养方向和就业路径。',tone:'warn'});
    if((p.reviewTags||[]).includes('learning_load')) tags.push({label:'强度需复核',type:'profile',priority:76,detail:'学生画像显示对学习强度较敏感，建议查看课程结构、实验实践、数学/代码/医学长周期要求。',tone:'warn'});
    if(type==='A') tags.push({label:'守底线',type:'abc',priority:65,detail:'A组优先守公办、费用、位次安全和路径清楚度。',tone:'soft'});
    if(type==='B') tags.push({label:'看专业',type:'abc',priority:65,detail:'B组优先看专业是否看得准、孩子是否认可、路径是否清楚。',tone:'soft'});
    if(type==='C') tags.push({label:'争上限',type:'abc',priority:65,detail:'C组优先比较学校平台、城市资源或层级上限，同时要接受更高不确定性。',tone:'soft'});
    return uniqTags(tags);
  }
  function visible(tags,max){ tags=tags||[]; const m=max||5; return {shown:tags.slice(0,m), hidden:tags.slice(m)}; }
  window.LN_CANDIDATE_DECISION_TAGS_V2981={build,visible,ready:true};
})();
